/* Downstream quiz engine.
 *
 * Questions come from window.QUIZ (generated by build.py from the data layer).
 * Scheduling lives in localStorage under 'ds-srs' and never leaves the browser.
 *
 *   ds-srs = { "<question id>": { n, due, last, right, wrong } }
 *
 *   n     how many times in a row it has been answered correctly
 *   due   epoch ms when it should come back
 */
(function () {
  'use strict';

  var KEY = 'ds-srs';
  var STEPS = [10 * 60e3, 864e5, 3 * 864e5, 7 * 864e5, 16 * 864e5, 35 * 864e5];

  function load() {
    try { return JSON.parse(localStorage.getItem(KEY)) || {}; } catch (e) { return {}; }
  }

  function save(s) {
    try { localStorage.setItem(KEY, JSON.stringify(s)); } catch (e) {}
  }

  function record(id, ok) {
    var s = load();
    var r = s[id] || { n: 0, due: 0, last: 0, right: 0, wrong: 0 };
    if (ok) { r.n = Math.min(r.n + 1, STEPS.length - 1); r.right++; }
    else { r.n = 0; r.wrong++; }
    r.last = Date.now();
    r.due = Date.now() + STEPS[ok ? r.n : 0];
    s[id] = r;
    save(s);
    return r;
  }

  /* ---------------------------------------------------------------- picking */

  function shuffled(a) {
    a = a.slice();
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  function pick(pool, n, mode) {
    var s = load(), now = Date.now();
    var unseen = [], due = [], later = [], weak = [];
    pool.forEach(function (q) {
      var r = s[q.id];
      if (!r) { unseen.push(q); return; }
      if (r.wrong > 1 && r.wrong >= r.right) weak.push(q);
      (r.due <= now ? due : later).push(q);
    });

    var order;
    if (mode === 'weak') order = shuffled(weak);
    else if (mode === 'all') order = shuffled(pool);
    else order = shuffled(due).concat(shuffled(unseen), shuffled(later));

    return n > 0 ? order.slice(0, n) : order;
  }

  /* --------------------------------------------------------------- rendering */

  var base = (document.body && document.body.getAttribute('data-base')) || '';

  function esc(s) {
    return String(s).replace(/&(?!#?\w+;)/g, '&amp;').replace(/</g, '&lt;');
  }

  function card(q, idx, total) {
    var head = total > 1
      ? '<p class="qmeta"><span class="qcount">' + (idx + 1) + ' / ' + total +
        '</span><span class="qtopic">' + esc(q.topic) + '</span></p>'
      : '<p class="qmeta"><span class="qtopic">' + esc(q.topic) + '</span></p>';

    var bodyHtml;
    if (q.kind === 'order') {
      bodyHtml = '<ol class="qorder" data-order>' + q.items.map(function (it, i) {
        return '<li><button type="button" class="qopt" data-i="' + i + '">' +
          it + '</button></li>';
      }).join('') + '</ol><p class="qhint">Click them in order, first to last.</p>';
    } else {
      bodyHtml = '<ul class="qchoices">' + q.choices.map(function (ch, i) {
        return '<li><button type="button" class="qopt" data-i="' + i + '">' +
          ch + '</button></li>';
      }).join('') + '</ul>';
    }

    return '<article class="qcard" data-id="' + q.id + '">' + head +
      '<p class="qstem">' + q.stem + '</p>' + bodyHtml +
      '<div class="qwhy" hidden><p class="qverdict"></p><p class="qexpl">' +
      esc(q.why || '') + '</p><p class="qlinks">' +
      (q.page ? '<a href="' + base + q.page + '">Read the page &rarr;</a>' : '') +
      (q.ref ? '<span class="qref">' + esc(q.ref) + '</span>' : '') +
      '</p></div></article>';
  }

  /* Runs a list of questions inside a container. onDone gets the score. */
  function run(host, list, onDone) {
    var i = 0, right = 0, missed = [];

    function step() {
      if (i >= list.length) {
        host.innerHTML =
          '<div class="qdone"><p class="qscore">' + right + ' / ' + list.length +
          '</p><p>' + (missed.length
            ? 'Coming back sooner: ' + missed.map(function (q) {
                return '<a href="' + base + (q.page || '') + '">' +
                  esc(q.topic.toLowerCase()) + '</a>';
              }).slice(0, 6).join(', ')
            : 'Nothing missed.') +
          '</p><button class="qstart" type="button" data-again>Go again</button></div>';
        var again = host.querySelector('[data-again]');
        if (again) again.addEventListener('click', function () { onDone(true); });
        else onDone(false);
        return;
      }

      var q = list[i];
      host.innerHTML = card(q, i, list.length);
      var el = host.querySelector('.qcard');
      var why = el.querySelector('.qwhy');
      var verdict = el.querySelector('.qverdict');
      var opts = [].slice.call(el.querySelectorAll('.qopt'));

      function finish(ok) {
        record(q.id, ok);
        if (ok) right++; else missed.push(q);
        verdict.textContent = ok ? 'Correct' : 'Not quite';
        verdict.className = 'qverdict ' + (ok ? 'ok' : 'no');
        why.hidden = false;
        var next = document.createElement('button');
        next.type = 'button';
        next.className = 'qnext';
        next.textContent = i + 1 < list.length ? 'Next question' : 'See the score';
        next.addEventListener('click', function () { i++; step(); });
        why.appendChild(next);
        next.focus();
      }

      if (q.kind === 'order') {
        var want = q.answer, at = 0, wrong = false;
        opts.forEach(function (b) {
          b.addEventListener('click', function () {
            if (b.disabled) return;
            var ok = b.textContent === want[at];
            if (!ok) { wrong = true; b.classList.add('bad'); return; }
            b.classList.add('good');
            b.disabled = true;
            b.insertAdjacentHTML('afterbegin', '<span class="qnum">' + (at + 1) + '</span>');
            at++;
            if (at === want.length) finish(!wrong);
          });
        });
      } else {
        opts.forEach(function (b) {
          b.addEventListener('click', function () {
            if (el.classList.contains('answered')) return;
            el.classList.add('answered');
            var ok = +b.getAttribute('data-i') === q.answer;
            opts.forEach(function (o, n) {
              o.disabled = true;
              if (n === q.answer) o.classList.add('good');
            });
            if (!ok) b.classList.add('bad');
            finish(ok);
          });
        });
      }
    }

    step();
  }

  /* ------------------------------------------------------------- quiz page */

  function quizPage() {
    var setup = document.getElementById('setup');
    var host = document.getElementById('run');
    if (!setup || !host || !window.QUIZ) return;

    var fSys = document.getElementById('f-sys');
    var fTop = document.getElementById('f-top');
    var fLen = document.getElementById('f-len');
    var fMode = document.getElementById('f-mode');
    var stat = document.getElementById('qstat');
    var meta = document.getElementById('quizmeta');

    function pool() {
      return window.QUIZ.filter(function (q) {
        if (fSys.value && q.system !== fSys.value) return false;
        if (fTop.value && q.topic !== fTop.value) return false;
        return true;
      });
    }

    function counts() {
      var s = load(), now = Date.now(), p = pool();
      var due = 0, unseen = 0;
      p.forEach(function (q) {
        var r = s[q.id];
        if (!r) unseen++;
        else if (r.due <= now) due++;
      });
      stat.innerHTML = p.length + ' in this selection &middot; <b>' + due +
        '</b> due now &middot; ' + unseen + ' never seen';
      progress();
      weakspots();
    }

    function progress() {
      var box = document.getElementById('prog');
      if (!box) return;
      var s = load(), ids = Object.keys(s);
      if (!ids.length) { box.innerHTML = '<p class="tiny">No history yet.</p>'; return; }
      var right = 0, wrong = 0, learned = 0;
      ids.forEach(function (k) {
        right += s[k].right; wrong += s[k].wrong;
        if (s[k].n >= 3) learned++;
      });
      var pct = right + wrong ? Math.round(100 * right / (right + wrong)) : 0;
      box.innerHTML = '<p class="tiny"><b>' + ids.length + '</b> questions seen &middot; <b>' +
        pct + '%</b> correct all-time &middot; <b>' + learned + '</b> sticking</p>';
    }

    function weakspots() {
      var box = document.getElementById('weak');
      if (!box) return;
      var s = load();
      var rows = window.QUIZ.filter(function (q) {
        var r = s[q.id];
        return r && r.wrong > 1;
      }).sort(function (a, b) { return s[b.id].wrong - s[a.id].wrong; }).slice(0, 12);
      if (!rows.length) {
        box.innerHTML = '<p class="tiny">Nothing yet &mdash; answer some questions first.</p>';
        return;
      }
      box.innerHTML = '<div class="weaklist">' + rows.map(function (q) {
        return '<a class="weakrow" href="' + base + (q.page || '') + '">' +
          '<span class="wq">' + q.stem + '</span>' +
          '<span class="wn">missed ' + s[q.id].wrong + '&times;</span></a>';
      }).join('') + '</div>';
    }

    function start() {
      var list = pick(pool(), +fLen.value, fMode.value);
      if (!list.length) {
        stat.innerHTML = 'Nothing to ask with those filters &mdash; try a different mode.';
        return;
      }
      setup.hidden = true;
      if (meta) meta.hidden = true;
      host.hidden = false;
      host.scrollIntoView({ block: 'start', behavior: 'smooth' });
      run(host, list, function (again) {
        if (again) { start(); return; }
        host.hidden = true;
        setup.hidden = false;
        if (meta) meta.hidden = false;
        counts();
      });
    }

    document.getElementById('qstart').addEventListener('click', start);
    [fSys, fTop, fMode].forEach(function (el) {
      el.addEventListener('change', counts);
    });

    var reset = document.getElementById('qreset');
    if (reset) {
      reset.addEventListener('click', function () {
        if (!window.confirm('Wipe all quiz history in this browser?')) return;
        save({});
        counts();
      });
    }

    counts();
  }

  /* ------------------------------------------------- per-page drill blocks */

  function drills() {
    [].slice.call(document.querySelectorAll('.drill[data-drill]')).forEach(function (sec) {
      if (!window.QUIZ) return;
      var path = sec.getAttribute('data-drill');
      var mine = window.QUIZ.filter(function (q) { return q.page === path; });
      if (mine.length < 2) return;

      sec.hidden = false;
      var body = sec.querySelector('.drillbody');

      function idle() {
        body.innerHTML = '<p class="tiny">' + mine.length +
          ' questions from this page.</p>' +
          '<button class="qstart small" type="button">Start</button>';
        body.querySelector('button').addEventListener('click', go);
      }

      function go() {
        var list = pick(mine, Math.min(5, mine.length), 'due');
        if (!list.length) list = shuffled(mine).slice(0, 5);
        run(body, list, function (again) {
          if (again) go(); else idle();
        });
      }

      idle();
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { quizPage(); drills(); });
  } else {
    quizPage();
    drills();
  }
})();
